  ('6a32c6fd-6893-5bc7-a442-0743795ee10d', null, (select id from public.skills where slug = 'write-g8-paragraph-transitions'), null, 'hard',
   $q$Which sentence uses a transition that correctly shows the relationship between its ideas?$q$, $q$[{"text":"The gym was closed for repairs; for example, the team practiced outside.","is_correct":false,"misconception_token":"example-for-cause"},{"text":"It was raining very heavily; nevertheless, the game was canceled.","is_correct":false,"misconception_token":"concession-for-cause"},{"text":"Ravi practiced free throws every night; however, his shooting improved.","is_correct":false,"misconception_token":"contrast-for-cause"},{"text":"Ravi practiced free throws every night; consequently, his shooting improved.","is_correct":true}]$q$::jsonb, $q$Ravi practiced free throws every night; consequently, his shooting improved.$q$, $q$Nightly practice leads to better shooting, so "consequently" correctly shows cause and effect. "However" is wrong because improvement is the expected result of practice, not a surprise.$q$, 'draft', null)
